<div class="adm-form-section"><div class="adm-form-section-title">Verified payments awaiting partner ledger allocation</div><p class="muted">Only approved payment submissions linked to reviewed partner enrollments appear here. Confirm the partner attribution, tax, gateway fee, and collection owner before recording. This creates an immutable verified ledger row; the payment itself is never changed.</p><?php if(!$payments): ?><p class="muted">No approved partner-attributed payments need reconciliation.</p><?php else: ?><div class="adm-table-wrap"><table class="tcm-table"><thead><tr><th>Payment</th><th>Student</th><th>Course</th><th>Amount</th><th>Allocate</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td>#<?= (int)$p['id'] ?><br><?= e($p['payment_date']) ?><br><span class="muted"><?= e($p['transaction_ref']??'') ?></span></td><td><?= e($p['student_name']) ?></td><td><?= e($p['item_title']) ?></td><td>₹<?= number_format((float)$p['amount'],2) ?></td><td><form method="post" action="<?= base_url('/admin/partners/finance/payments/'.$p['id']) ?>"><?= csrf_field() ?><select class="form-select form-select-sm" name="partner_id"><?php foreach($partners as $partner): ?><option value="<?= (int)$partner['id'] ?>" <?= (int)$partner['id']===(int)$p['partner_id']?'selected':'' ?>><?= e($partner['display_name']) ?></option><?php endforeach ?></select><div style="display:flex;gap:4px;margin:5px 0"><input class="form-control form-control-sm" type="number" min="0" step=".01" name="tax_amount" placeholder="Tax ₹"><input class="form-control form-control-sm" type="number" min="0" step=".01" name="gateway_fee" placeholder="Gateway ₹"></div><select class="form-select form-select-sm" name="collection_owner"><option value="tcm">TCM One collected</option><option value="partner">Partner collected</option></select><button class="tcm-btn primary sm" style="margin-top:5px">Record Verified Payment</button></form></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></div>
<div class="adm-form-section"><div class="adm-form-section-title">Create a settlement request</div><p class="muted">Amount cannot exceed the verified outstanding balance for the selected direction. Approval does not mark a transfer as paid.</p><form method="post" action="<?= base_url('/admin/partners/finance/settlements') ?>" class="row g-2"><?= csrf_field() ?><div class="col-md-4"><label class="form-label">Partner</label><select name="partner_id" class="form-select" required><?php foreach($partners as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['display_name']) ?></option><?php endforeach ?></select></div><div class="col-md-3"><label class="form-label">Direction</label><select name="direction" class="form-select"><option value="tcm_owes_partner">TCM One pays partner</option><option value="partner_owes_tcm">Partner pays TCM One</option></select></div><div class="col-md-2"><label class="form-label">Amount ₹</label><input type="number" min=".01" step=".01" name="amount" class="form-control" required></div><div class="col-md-3"><label class="form-label">Note</label><input name="note" class="form-control"></div><div class="col-12"><button class="tcm-btn primary">Create Pending Settlement</button></div></form></div>
<div class="adm-form-section"><div class="adm-form-section-title">Ledger history</div><div class="adm-table-wrap"><table class="tcm-table"><thead><tr><th>Partner / Student</th><th>Payment source</th><th>Collection owner</th><th>Gross</th><th>Eligible</th><th>Entitlements</th><th>Status</th></tr></thead><tbody><?php if(!$entries): ?><tr><td colspan="7">No financial ledger entries.</td></tr><?php endif ?><?php foreach($entries as $e1): ?><tr><td><?= e($e1['display_name']) ?><br><?= e($e1['student_name']??'') ?></td><td><?= e($e1['description']??'') ?><br><span class="muted">Payment #<?= e($e1['payment_submission_id']??'—') ?></span></td><td><?= e($e1['collection_owner']) ?></td><td>₹<?= number_format((float)$e1['gross_amount'],2) ?></td><td>₹<?= number_format((float)$e1['eligible_amount'],2) ?></td><td>Partner ₹<?= number_format((float)$e1['partner_entitlement'],2) ?><br>TCM ₹<?= number_format((float)$e1['tcm_entitlement'],2) ?></td><td><?= e($e1['status']) ?></td></tr><?php endforeach ?></tbody></table></div></div>
<div class="adm-form-section"><div class="adm-form-section-title">Settlement verification and transfer history</div><div class="adm-table-wrap"><table class="tcm-table"><thead><tr><th>Partner</th><th>Direction</th><th>Amount</th><th>Status</th><th>Reference / actions</th></tr></thead><tbody><?php if(!$settlements): ?><tr><td colspan="5">No settlements.</td></tr><?php endif ?><?php foreach($settlements as $s): ?><tr><td><?= e($s['display_name']) ?></td><td><?= e(str_replace('_',' ',$s['direction'])) ?></td><td>₹<?= number_format((float)$s['amount'],2) ?></td><td><?= e($s['status']) ?></td><td><?php if($s['status']==='pending_verification'): ?><form method="post" action="<?= base_url('/admin/partners/finance/settlements/'.$s['id']) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="approve"><button class="tcm-btn primary sm">Approve</button></form><?php elseif($s['status']==='approved'): ?><form method="post" action="<?= base_url('/admin/partners/finance/settlements/'.$s['id']) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="settled"><input name="reference" class="form-control form-control-sm" placeholder="NEFT / RTGS reference" required><button class="tcm-btn primary sm">Record Transfer</button></form><?php else: ?><?= e($s['reference']??'—') ?><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></div>
